Find all quadratic residues and non-residues modulo $7$.

\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Compute $x^2 \pmod{7}$ for $x = 1, 2, 3$ (only need up to $(p-1)/2 = 3$):

\begin{center}
\begin{tabular}{|c|c|c|}
\hline
\rowcolor{primaryblue!20}
$x$ & $x^2$ & $x^2 \pmod{7}$ \\
\hline
1 & 1  & 1 \\
\hline
2 & 4  & 4 \\
\hline
3 & 9  & 2 \\
\hline
\end{tabular}
\end{center}

\textbf{Step 2:} Note that $4^2 \equiv 16 \equiv 2$, $5^2 \equiv 25 \equiv 4$,
$6^2 \equiv 36 \equiv 1 \pmod{7}$, giving the same set.

\textbf{Quadratic Residues mod 7:} $\{1, 2, 4\}$

\textbf{Quadratic Non-Residues mod 7:} $\{3, 5, 6\}$

\textbf{Verification:} There are $\dfrac{7-1}{2} = 3$ QRs and $3$ QNRs. \textcolor{green}{\checkmark}

Determine whether $x^2 \equiv 5 \pmod{19}$ is solvable.

\textcolor{primaryblue}{\textbf{Solution:}}

Here $a = 5$, $p = 19$. Check $\gcd(5, 19) = 1$. \textcolor{green}{\checkmark}

By Euler's Criterion, compute $a^{(p-1)/2} = 5^9 \pmod{19}$.

\textbf{Step 1:} Compute powers of $5$ modulo $19$ using repeated squaring:
\begin{align*}
5^1 &\equiv 5 \pmod{19}\\
5^2 &\equiv 25 \equiv 6 \pmod{19}\\
5^4 &\equiv 6^2 = 36 \equiv 17 \equiv -2 \pmod{19}\\
5^8 &\equiv (-2)^2 = 4 \pmod{19}\\
5^9 &= 5^8 \cdot 5^1 \equiv 4 \cdot 5 = 20 \equiv 1 \pmod{19}
\end{align*}

\textbf{Step 2:} Since $5^9 \equiv 1 \pmod{19}$, by Euler's Criterion,
$5$ is a \textbf{quadratic residue} modulo $19$.

\textcolor{green}{\textbf{Conclusion:}} The congruence $x^2 \equiv 5 \pmod{19}$
\textbf{is solvable}. \textcolor{green}{\checkmark}

Determine whether $x^2 \equiv 2 \pmod{11}$ is solvable.

\textcolor{primaryblue}{\textbf{Solution:}}

Here $a = 2$, $p = 11$. Check $\gcd(2, 11) = 1$. \textcolor{green}{\checkmark}

By Euler's Criterion, compute $a^{(p-1)/2} = 2^5 \pmod{11}$.

\textbf{Step 1:}
\[
2^5 = 32 = 2(11) + 10 \equiv 10 \equiv -1 \pmod{11}
\]

\textbf{Step 2:} Since $2^5 \equiv -1 \pmod{11}$, by the Corollary,
$2$ is a \textbf{quadratic non-residue} modulo $11$.

\textcolor{green}{\textbf{Conclusion:}} The congruence $x^2 \equiv 2 \pmod{11}$
\textbf{has no solution}. \textcolor{red}{$\times$}

\textbf{Verification from Example 2:} The QRs modulo $11$ are $\{1, 3, 4, 5, 9\}$,
and $2$ does not appear. \textcolor{green}{\checkmark}

Determine whether $x^2 \equiv 8 \pmod{13}$ is solvable.

\textcolor{primaryblue}{\textbf{Solution:}}

Here $a = 8$, $p = 13$. Check $\gcd(8, 13) = 1$. \textcolor{green}{\checkmark}

By Euler's Criterion, compute $a^{(p-1)/2} = 8^6 \pmod{13}$.

\textbf{Step 1:} Compute using repeated squaring:
\begin{align*}
8^2 &= 64 = 4(13) + 12 \equiv 12 \equiv -1 \pmod{13}\\
8^4 &\equiv (-1)^2 = 1 \pmod{13}\\
8^6 &= 8^4 \cdot 8^2 \equiv 1 \cdot (-1) = -1 \pmod{13}
\end{align*}

\textbf{Step 2:} Since $8^6 \equiv -1 \pmod{13}$, by the Corollary,
$8$ is a \textbf{quadratic non-residue} modulo $13$.

\textcolor{green}{\textbf{Conclusion:}} The congruence $x^2 \equiv 8 \pmod{13}$
\textbf{has no solution}. \textcolor{red}{$\times$}

Determine whether $x^2 \equiv 13 \pmod{31}$ is solvable.

\textcolor{primaryblue}{\textbf{Solution:}}

Here $a = 13$, $p = 31$. Check $\gcd(13, 31) = 1$. \textcolor{green}{\checkmark}

By Euler's Criterion, compute $a^{(p-1)/2} = 13^{15} \pmod{31}$.

\textbf{Step 1:} Use repeated squaring:
\begin{align*}
13^2 &= 169 = 5(31) + 14 \equiv 14 \pmod{31}\\
13^4 &\equiv 14^2 = 196 = 6(31) + 10 \equiv 10 \pmod{31}\\
13^8 &\equiv 10^2 = 100 = 3(31) + 7 \equiv 7 \pmod{31}
\end{align*}

\textbf{Step 2:} Write $15 = 8 + 4 + 2 + 1$:
\begin{align*}
13^{15} &= 13^8 \cdot 13^4 \cdot 13^2 \cdot 13^1\\
         &\equiv 7 \cdot 10 \cdot 14 \cdot 13 \pmod{31}
\end{align*}

Compute step by step:
\begin{align*}
7 \times 10 &= 70 = 2(31) + 8 \equiv 8 \pmod{31}\\
8 \times 14 &= 112 = 3(31) + 19 \equiv 19 \pmod{31}\\
19 \times 13 &= 247 = 7(31) + 30 \equiv 30 \equiv -1 \pmod{31}
\end{align*}

\textbf{Step 3:} Since $13^{15} \equiv -1 \pmod{31}$, by the Corollary,
$13$ is a \textbf{quadratic non-residue} modulo $31$.

\textcolor{green}{\textbf{Conclusion:}} The congruence $x^2 \equiv 13 \pmod{31}$
\textbf{has no solution}. \textcolor{red}{$\times$}

\textcolor{primaryblue}{\faCheckCircle\ \textbf{Summary: Quadratic Residues and Euler's Criterion}}

\textbf{For an odd prime $p$ and $\gcd(a,p) = 1$:}

\begin{center}
\begin{tabular}{|p{5cm}|p{7cm}|}
\hline
\rowcolor{primaryblue!20}
\textbf{Condition} & \textbf{Conclusion} \\
\hline
$a^{(p-1)/2} \equiv 1 \pmod p$ & $a$ is a QR mod $p$; $x^2 \equiv a$ is solvable \\
\hline
$a^{(p-1)/2} \equiv -1 \pmod p$ & $a$ is a QNR mod $p$; $x^2 \equiv a$ has no solution \\
\hline
\end{tabular}
\end{center}

\textbf{Counting:}
\begin{itemize}[leftmargin=*]
    \item Exactly $\dfrac{p-1}{2}$ quadratic residues among $\{1, 2, \ldots, p-1\}$
    \item Exactly $\dfrac{p-1}{2}$ quadratic non-residues among $\{1, 2, \ldots, p-1\}$
    \item If $x_0$ is a solution of $x^2 \equiv a \pmod p$, then $p - x_0$ is the other
\end{itemize}

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Method: Repeated Squaring}}

To compute $a^{(p-1)/2} \pmod p$ efficiently:
\begin{enumerate}[leftmargin=*]
    \item Write $(p-1)/2$ in binary (as a sum of powers of $2$)
    \item Compute $a^1, a^2, a^4, a^8, \ldots$ by successive squaring
    \item Multiply the relevant powers together
\end{enumerate}

\newpage

Use property (iii) to solve $x^2 \equiv 4 \pmod{11}$, given $p \equiv 3 \pmod{4}$.

\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Check $p = 11$. Is $11 \equiv 3 \pmod 4$?
$11 = 2(4) + 3$, so yes. \textcolor{green}{\checkmark}

\textbf{Step 2:} Check $a = 4$ is a QR mod $11$.
From Example 2, $4 \in \{1,3,4,5,9\}$. \textcolor{green}{\checkmark}

\textbf{Step 3:} Apply the formula $x \equiv \pm\, a^{(p+1)/4} \pmod{p}$:
\[
\frac{p+1}{4} = \frac{12}{4} = 3
\]
\[
x \equiv \pm\, 4^3 = \pm\, 64 \equiv \pm\, 9 \pmod{11}
\]

So $x \equiv 9 \pmod{11}$ or $x \equiv -9 \equiv 2 \pmod{11}$.

\textbf{Solutions:} $\boxed{x \equiv 2 \text{ and } x \equiv 9 \pmod{11}}$

\textbf{Verification:}
$2^2 = 4 \equiv 4 \pmod{11}$ \textcolor{green}{\checkmark} \quad
$9^2 = 81 = 7(11) + 4 \equiv 4 \pmod{11}$ \textcolor{green}{\checkmark}

\newpage

Evaluate $\left(\dfrac{6}{13}\right)$ and $\left(\dfrac{11}{13}\right)$.

\textcolor{primaryblue}{\textbf{Solution:}}

Here $p = 13$, so $(p-1)/2 = 6$.

\textbf{(a)} $\left(\dfrac{6}{13}\right)$: Compute $6^6 \pmod{13}$:
\begin{align*}
6^2 &= 36 = 2(13) + 10 \equiv 10 \pmod{13}\\
6^3 &\equiv 10 \cdot 6 = 60 = 4(13) + 8 \equiv 8 \pmod{13}\\
6^6 &\equiv 8^2 = 64 = 4(13) + 12 \equiv 12 \equiv -1 \pmod{13}
\end{align*}
So $\left(\dfrac{6}{13}\right) = -1$ (QNR). \textcolor{green}{\checkmark}

\textbf{(b)} $\left(\dfrac{11}{13}\right)$: Note $11 \equiv -2 \pmod{13}$. Compute $(-2)^6 \pmod{13}$:
\[
(-2)^6 = 2^6 = 64 = 4(13) + 12 \equiv 12 \equiv -1 \pmod{13}
\]
So $\left(\dfrac{11}{13}\right) = -1$ (QNR). \textcolor{green}{\checkmark}

\newpage

If $p$ is an odd prime, then:
\[
\left(\frac{-1}{p}\right) = (-1)^{\frac{p-1}{2}}
\]

More explicitly:
\[
\left(\frac{-1}{p}\right) =
\begin{cases}
\phantom{-}1  & \text{if } p \equiv 1 \pmod{4} \\
-1 & \text{if } p \equiv 3 \pmod{4}
\end{cases}
\]

\textcolor{primaryblue}{\faInfoCircle\ \textbf{In words:}}
$-1$ is a quadratic residue modulo $p$ if and only if $p \equiv 1 \pmod 4$.

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Note:}} Statement only.

For each prime, determine whether $-1$ is a QR or QNR:
$p = 5$, $p = 13$, $p = 7$, $p = 19$.

\textcolor{primaryblue}{\textbf{Solution:}}

\begin{center}
\begin{tabular}{|c|c|c|c|}
\hline
\rowcolor{primaryblue!20}
$p$ & $p \pmod 4$ & $\left(\dfrac{-1}{p}\right)$ & $-1$ is a \ldots \\
\hline
5  & $1$ & $\phantom{-}1$  & QR \textcolor{green}{\checkmark} \\
\hline
13 & $1$ & $\phantom{-}1$  & QR \textcolor{green}{\checkmark} \\
\hline
7  & $3$ & $-1$ & QNR \textcolor{red}{$\times$} \\
\hline
19 & $3$ & $-1$ & QNR \textcolor{red}{$\times$} \\
\hline
\end{tabular}
\end{center}

\textbf{Verification for $p = 5$:}
$(-1)^{(5-1)/2} = (-1)^2 = 1$, so $\left(\dfrac{-1}{5}\right) = 1$.

Check: $x^2 \equiv -1 \equiv 4 \pmod 5$ has solution $x = 2$
since $2^2 = 4$. \textcolor{green}{\checkmark}

\textbf{Verification for $p = 7$:}
$(-1)^{(7-1)/2} = (-1)^3 = -1$, so $\left(\dfrac{-1}{7}\right) = -1$.

Check: none of $1^2,2^2,3^2,4^2,5^2,6^2 \pmod 7$ gives $6 \equiv -1$.
The squares mod 7 are $\{1,2,4\}$ and $6 \notin \{1,2,4\}$. \textcolor{green}{\checkmark}

Evaluate $\left(\dfrac{-3}{13}\right)$.

\textcolor{primaryblue}{\textbf{Solution:}}

Write $-3 = (-1) \cdot 3$. By the multiplicative property:
\[
\left(\frac{-3}{13}\right) = \left(\frac{-1}{13}\right)\left(\frac{3}{13}\right)
\]

\textbf{Step 1:} $p = 13 \equiv 1 \pmod 4$, so $\left(\dfrac{-1}{13}\right) = 1$.

\textbf{Step 2:} Compute $\left(\dfrac{3}{13}\right)$ using Euler's Criterion:
\[
3^{(13-1)/2} = 3^6 \pmod{13}
\]
\begin{align*}
3^2 &= 9 \pmod{13}\\
3^4 &\equiv 81 = 6(13) + 3 \equiv 3 \pmod{13}\\
3^6 &\equiv 3^4 \cdot 3^2 \equiv 3 \cdot 9 = 27 = 2(13) + 1 \equiv 1 \pmod{13}
\end{align*}
So $\left(\dfrac{3}{13}\right) = 1$.

\textbf{Step 3:}
\[
\left(\frac{-3}{13}\right) = (1)(1) = 1
\]

So $-3$ is a QR modulo $13$. \textcolor{green}{\checkmark}

\textcolor{primaryblue}{\faCheckCircle\ \textbf{Summary: Legendre Symbol and Its Properties}}

\textbf{Definition:}
$\left(\dfrac{a}{p}\right) = 1$ if $a$ is QR mod $p$,
and $\left(\dfrac{a}{p}\right) = -1$ if $a$ is QNR mod $p$.

\begin{center}
\begin{tabular}{|p{4.5cm}|p{7.5cm}|}
\hline
\rowcolor{primaryblue!20}
\textbf{Property} & \textbf{Statement} \\
\hline
Euler's Criterion & $\left(\dfrac{a}{p}\right) \equiv a^{(p-1)/2} \pmod p$ \\
\hline
Property 1 (Multiplicative) & $\left(\dfrac{ab}{p}\right) = \left(\dfrac{a}{p}\right)\left(\dfrac{b}{p}\right)$ \\
\hline
Property 2 (Square multiple) & $\left(\dfrac{ab^2}{p}\right) = \left(\dfrac{a}{p}\right)$ \\
\hline
Property 3 (Symbol of 1) & $\left(\dfrac{1}{p}\right) = 1$ \\
\hline
Symbol of $-1$ & $\left(\dfrac{-1}{p}\right) = (-1)^{(p-1)/2}$ \\
\hline
\end{tabular}
\end{center}

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{QR Multiplication Table:}}
\begin{center}
\begin{tabular}{|c|c|c|}
\hline
\rowcolor{primaryblue!20}
$\times$ & QR & QNR \\
\hline
QR  & \cellcolor{green!20}QR  & \cellcolor{red!20}QNR \\
\hline
QNR & \cellcolor{red!20}QNR & \cellcolor{green!20}QR  \\
\hline
\end{tabular}
\end{center}

\newpage

Find the least residues of $1 \cdot 3,\; 2 \cdot 3,\; 3 \cdot 3$ modulo $7$.

\textcolor{primaryblue}{\textbf{Solution:}}

Here $p = 7$, so least residues lie in $\{-3, -2, -1, 1, 2, 3\}$.

\begin{center}
\begin{tabular}{|c|c|c|c|}
\hline
\rowcolor{primaryblue!20}
$k$ & $3k$ & Ordinary residue mod 7 & Least residue \\
\hline
1 & 3 & 3 & $\phantom{-}3$ \\
\hline
2 & 6 & 6 & $6 - 7 = -1$ \\
\hline
3 & 9 & 2 & $\phantom{-}2$ \\
\hline
\end{tabular}
\end{center}

The least residues are: $3, -1, 2$.

The \textbf{negative} least residue is: $-1$, so $\nu = 1$ negative one.

Use Gauss's Lemma to evaluate $\left(\dfrac{3}{7}\right)$.

\textcolor{primaryblue}{\textbf{Solution:}}

Here $a = 3$, $p = 7$, $\dfrac{p-1}{2} = 3$.

\textbf{Step 1:} Compute $3k \pmod 7$ and find least residues:

\begin{center}
\begin{tabular}{|c|c|c|c|c|}
\hline
\rowcolor{primaryblue!20}
$k$ & $3k$ & Ordinary residue mod 7 & Least residue $r_k$ & Sign \\
\hline
1 & 3 & 3 & $\phantom{-}3$ & $+$ \\
\hline
2 & 6 & 6 & $6-7=-1$       & $-$ \\
\hline
3 & 9 & 2 & $\phantom{-}2$ & $+$ \\
\hline
\end{tabular}
\end{center}

\textbf{Step 2:} Negative least residues: only $r_2 = -1$, so $\nu = 1$.

\textbf{Step 3:}
\[
\left(\frac{3}{7}\right) = (-1)^1 = -1
\]

So $3$ is a \textbf{quadratic non-residue} modulo $7$. \textcolor{red}{$\times$}

\textbf{Verification from Example 1:} $3 \in \{3,5,6\}$ (QNRs mod 7). \textcolor{green}{\checkmark}

Use Gauss's Lemma to evaluate $\left(\dfrac{5}{13}\right)$.

\textcolor{primaryblue}{\textbf{Solution:}}

Here $a = 5$, $p = 13$, $\dfrac{p-1}{2} = 6$.

\textbf{Step 1:} Compute $5k \pmod{13}$ and find least residues:

\begin{center}
\begin{tabular}{|c|c|c|c|c|}
\hline
\rowcolor{primaryblue!20}
$k$ & $5k$ & Ordinary residue mod 13 & Least residue $r_k$ & Sign \\
\hline
1 & 5  & 5  & $\phantom{-}5$   & $+$ \\
\hline
2 & 10 & 10 & $10-13=-3$       & $-$ \\
\hline
3 & 15 & 2  & $\phantom{-}2$   & $+$ \\
\hline
4 & 20 & 7  & $7-13=-6$        & $-$ \\
\hline
5 & 25 & 12 & $12-13=-1$       & $-$ \\
\hline
6 & 30 & 4  & $\phantom{-}4$   & $+$ \\
\hline
\end{tabular}
\end{center}

\textbf{Step 2:} Negative least residues: $r_2 = -3$, $r_4 = -6$, $r_5 = -1$.
So $\nu = 3$.

\textbf{Step 3:}
\[
\left(\frac{5}{13}\right) = (-1)^3 = -1
\]

So $5$ is a \textbf{quadratic non-residue} modulo $13$. \textcolor{red}{$\times$}

\textbf{Verification using Euler's Criterion:}
$5^6 \pmod{13}$:
\begin{align*}
5^2 &= 25 \equiv 12 \equiv -1 \pmod{13}\\
5^6 &= (5^2)^3 \equiv (-1)^3 = -1 \pmod{13}
\end{align*}
So $\left(\dfrac{5}{13}\right) = -1$. \textcolor{green}{\checkmark}

Let $p$ be an odd prime. Then:
\[
\left(\frac{2}{p}\right) = (-1)^{\frac{p^2-1}{8}}
\]

More explicitly:
\[
\left(\frac{2}{p}\right) =
\begin{cases}
\phantom{-}1  & \text{if } p \equiv \pm 1 \pmod{8} \\
-1 & \text{if } p \equiv \pm 3 \pmod{8}
\end{cases}
\]

\textcolor{primaryblue}{\faInfoCircle\ \textbf{In words:}}
$2$ is a quadratic residue modulo $p$ precisely when $p \equiv 1$ or $p \equiv 7 \pmod 8$.

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Note:}} Statement only.

Evaluate $\left(\dfrac{2}{p}\right)$ for $p = 7,\, 17,\, 11,\, 23$.

\textcolor{primaryblue}{\textbf{Solution:}}

Determine $p \pmod 8$ for each prime:

\begin{center}
\begin{tabular}{|c|c|c|c|}
\hline
\rowcolor{primaryblue!20}
$p$ & $p \pmod 8$ & $\left(\dfrac{2}{p}\right)$ & $2$ is a \ldots \\
\hline
7  & $7 \equiv -1$ & $\phantom{-}1$  & QR \textcolor{green}{\checkmark} \\
\hline
17 & $1$           & $\phantom{-}1$  & QR \textcolor{green}{\checkmark} \\
\hline
11 & $3$           & $-1$ & QNR \textcolor{red}{$\times$} \\
\hline
23 & $7 \equiv -1$ & $\phantom{-}1$  & QR \textcolor{green}{\checkmark} \\
\hline
\end{tabular}
\end{center}

\textbf{Verification for $p = 7$:}
$2^{(7-1)/2} = 2^3 = 8 \equiv 1 \pmod 7$,
so $\left(\dfrac{2}{7}\right) = 1$. \textcolor{green}{\checkmark}

\textbf{Verification for $p = 11$:}
$2^{(11-1)/2} = 2^5 = 32 \equiv 10 \equiv -1 \pmod{11}$,
so $\left(\dfrac{2}{11}\right) = -1$. \textcolor{green}{\checkmark}

\textcolor{primaryblue}{\faCheckCircle\ \textbf{Summary: Legendre Symbol of 2 and Quadratic Reciprocity}}

\textbf{Symbol of 2:}
\begin{center}
\begin{tabular}{|c|c|}
\hline
\rowcolor{primaryblue!20}
$p \pmod 8$ & $\left(\dfrac{2}{p}\right)$ \\
\hline
$\pm 1$ & $\phantom{-}1$ (QR) \\
\hline
$\pm 3$ & $-1$ (QNR) \\
\hline
\end{tabular}
\end{center}

\textbf{Quadratic Reciprocity Law:}
\[
\left(\frac{p}{q}\right)\left(\frac{q}{p}\right) = (-1)^{\frac{p-1}{2} \cdot \frac{q-1}{2}}
\]

\begin{center}
\begin{tabular}{|c|c|c|}
\hline
\rowcolor{primaryblue!20}
$p \pmod 4$ & $q \pmod 4$ & $\left(\dfrac{p}{q}\right)\left(\dfrac{q}{p}\right)$ \\
\hline
$1$ & any & $\phantom{-}1$ \\
\hline
any & $1$ & $\phantom{-}1$ \\
\hline
$3$ & $3$ & $-1$ \\
\hline
\end{tabular}
\end{center}

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Strategy for Evaluating $\left(\dfrac{a}{p}\right)$:}}
\begin{enumerate}[leftmargin=*]
    \item Factor $a$ into primes: $a = (-1)^{e_0} \cdot 2^{e_1} \cdot q_1^{e_2} \cdots$
    \item Use multiplicativity to split the symbol
    \item Use the theorem on $\left(\dfrac{-1}{p}\right)$ and $\left(\dfrac{2}{p}\right)$
          for those factors
    \item Use the Reciprocity Law to flip $\left(\dfrac{q_i}{p}\right)$
          into $\left(\dfrac{p}{q_i}\right)$, then reduce modulo $q_i$
    \item Repeat until the top argument is small enough to read directly
\end{enumerate}

\newpage

Let $m$ and $n$ be odd positive integers and let $a$, $b$ be integers with
$\gcd(a, n) = \gcd(b, n) = \gcd(m, n) = 1$. Then:

\textbf{Property 1 (Congruence):}
If $a \equiv b \pmod n$, then $\left(\dfrac{a}{n}\right) = \left(\dfrac{b}{n}\right)$.

\textbf{Property 2 (Multiplicativity in top):}
\[
\left(\frac{ab}{n}\right) = \left(\frac{a}{n}\right)\left(\frac{b}{n}\right)
\]

\textbf{Property 3 (Multiplicativity in bottom):}
\[
\left(\frac{a}{mn}\right) = \left(\frac{a}{m}\right)\left(\frac{a}{n}\right)
\]

\textbf{Property 4 (Symbol of 1):}
\[
\left(\frac{1}{n}\right) = 1
\]

\textbf{Property 5 (Symbol of negative one):}
\[
\left(\frac{-1}{n}\right) = (-1)^{\frac{n-1}{2}}
\]

\textbf{Property 6 (Symbol of 2):}
\[
\left(\frac{2}{n}\right) = (-1)^{\frac{n^2-1}{8}}
\]

\textbf{Property 7 (Reciprocity for Jacobi symbols):}
\[
\left(\frac{m}{n}\right)\left(\frac{n}{m}\right) = (-1)^{\frac{m-1}{2} \cdot \frac{n-1}{2}}
\]

\textcolor{darkgreen}{\textbf{Proof:}}

Let $n = p_1^{e_1} p_2^{e_2} \cdots p_r^{e_r}$ and $m = q_1^{f_1} \cdots q_s^{f_s}$
be the prime factorizations of $n$ and $m$.

\textcolor{darkgreen}{\textbf{Property 1: Congruence}}

If $a \equiv b \pmod n$, then $a \equiv b \pmod{p_i}$ for each prime $p_i \mid n$.

Since the Legendre symbol depends only on the residue class:
\[
\left(\frac{a}{p_i}\right) = \left(\frac{b}{p_i}\right) \quad \text{for all } i
\]

Taking the product over all $i$:
\[
\left(\frac{a}{n}\right) = \left(\frac{b}{n}\right)
\]
\textcolor{green}{\checkmark}

\textcolor{darkgreen}{\textbf{Property 2: Multiplicativity in Top}}

By definition and the multiplicativity of the Legendre symbol:
\[
\left(\frac{ab}{n}\right)
= \prod_{i=1}^{r} \left(\frac{ab}{p_i}\right)^{e_i}
= \prod_{i=1}^{r} \left(\frac{a}{p_i}\right)^{e_i} \left(\frac{b}{p_i}\right)^{e_i}
= \left(\frac{a}{n}\right)\left(\frac{b}{n}\right)
\]
\textcolor{green}{\checkmark}

\textcolor{darkgreen}{\textbf{Property 3: Multiplicativity in Bottom}}

Each prime factor of $mn$ is a prime factor of $m$ or $n$.
By the definition of the Jacobi symbol:
\[
\left(\frac{a}{mn}\right)
= \prod_{\text{primes } p \mid mn} \left(\frac{a}{p}\right)^{v_p(mn)}
= \prod_{p \mid m} \left(\frac{a}{p}\right)^{v_p(m)} \cdot \prod_{p \mid n} \left(\frac{a}{p}\right)^{v_p(n)}
= \left(\frac{a}{m}\right)\left(\frac{a}{n}\right)
\]
where $v_p(k)$ denotes the exponent of $p$ in $k$. \textcolor{green}{\checkmark}

\textcolor{darkgreen}{\textbf{Property 4: Symbol of 1}}

$\left(\dfrac{1}{p_i}\right) = 1$ for every prime $p_i$. Taking the product:
\[
\left(\frac{1}{n}\right) = \prod_{i=1}^r 1^{e_i} = 1
\]
\textcolor{green}{\checkmark}

\textcolor{darkgreen}{\textbf{Property 5: Symbol of Negative One}}

By the theorem on the Legendre symbol of $-1$:
\[
\left(\frac{-1}{p_i}\right) = (-1)^{\frac{p_i - 1}{2}}
\]

Therefore:
\[
\left(\frac{-1}{n}\right) = \prod_{i=1}^r \left((-1)^{\frac{p_i-1}{2}}\right)^{e_i}
= (-1)^{\sum_{i=1}^r e_i \frac{p_i - 1}{2}}
\]

We use the identity: for odd $n = \prod p_i^{e_i}$:
\[
\frac{n-1}{2} \equiv \sum_{i=1}^r e_i \cdot \frac{p_i - 1}{2} \pmod 2
\]

This follows because $n = \prod p_i^{e_i}$ and modulo $2$:
$p_i^{e_i} \equiv 1 + e_i(p_i - 1) \pmod 4$, so
$n \equiv 1 + \sum e_i(p_i - 1) \pmod 4$.

Therefore $\dfrac{n-1}{2} \equiv \sum e_i \dfrac{p_i-1}{2} \pmod 2$, giving:
\[
\left(\frac{-1}{n}\right) = (-1)^{\frac{n-1}{2}}
\]
\textcolor{green}{\checkmark}

\textcolor{darkgreen}{\textbf{Property 6: Symbol of 2}}

By the theorem on $\left(\dfrac{2}{p}\right)$:
$\left(\dfrac{2}{p_i}\right) = (-1)^{\frac{p_i^2-1}{8}}$.

Therefore:
\[
\left(\frac{2}{n}\right) = (-1)^{\sum_{i=1}^r e_i \frac{p_i^2-1}{8}}
\]

Using the identity: $\dfrac{n^2-1}{8} \equiv \sum e_i \dfrac{p_i^2-1}{8} \pmod 2$,
which holds because $p^2 \equiv 1 \pmod 8$ for any odd prime $p$, and:
\[
n^2 = \prod p_i^{2e_i} \implies n^2 \equiv 1 + \sum 2e_i(p_i^2-1)/8 \cdot 8 \pmod{16}
\]

gives $\dfrac{n^2-1}{8} \equiv \sum e_i \dfrac{p_i^2-1}{8} \pmod 2$. Therefore:
\[
\left(\frac{2}{n}\right) = (-1)^{\frac{n^2-1}{8}}
\]
\textcolor{green}{\checkmark}

\textcolor{darkgreen}{\textbf{Property 7: Jacobi Reciprocity}}

For any two primes $p \mid m$ and $q \mid n$, the Legendre reciprocity gives:
\[
\left(\frac{p}{q}\right)\left(\frac{q}{p}\right) = (-1)^{\frac{p-1}{2} \cdot \frac{q-1}{2}}
\]

Therefore:
\[
\left(\frac{m}{n}\right)\left(\frac{n}{m}\right)
= \prod_{i,j} \left(\frac{q_i}{p_j}\right)^{f_i e_j} \left(\frac{p_j}{q_i}\right)^{e_j f_i}
= \prod_{i,j} (-1)^{f_i e_j \cdot \frac{q_i-1}{2} \cdot \frac{p_j-1}{2}}
= (-1)^{\left(\sum_j e_j \frac{p_j-1}{2}\right)\left(\sum_i f_i \frac{q_i-1}{2}\right)}
\]

Using Property 5's identity twice:
$\sum_j e_j \dfrac{p_j-1}{2} \equiv \dfrac{n-1}{2} \pmod 2$ and
$\sum_i f_i \dfrac{q_i-1}{2} \equiv \dfrac{m-1}{2} \pmod 2$.

Therefore:
\[
\left(\frac{m}{n}\right)\left(\frac{n}{m}\right) = (-1)^{\frac{n-1}{2} \cdot \frac{m-1}{2}}
\]

\textcolor{green}{\textbf{Conclusion:}} All seven properties are proved. \qed
